export class AppState { amount: number = 100.0; percentage: number = 10.0; part: number = 10.0; whole: number = 1000.0; }
export class ChangeAmount { value: number = 0.0; }
export class ChangePercentage { value: number = 0.0; }
export class Calculate {}
export function initialState(): AppState { return {amount: 100.0, percentage: 10.0, part: 10.0, whole: 1000.0}; }
// @ui-update
export function changeAmount(state: AppState, action: ChangeAmount): AppState { return {amount: action.value, percentage: state.percentage, part: state.part, whole: state.whole}; }
// @ui-update
export function changePercentage(state: AppState, action: ChangePercentage): AppState { return {amount: state.amount, percentage: action.value, part: state.part, whole: state.whole}; }
// @ui-update
export function calculate(state: AppState, action: Calculate): AppState { let part: number = (state.amount * state.percentage) / 100.0; let whole: number = 0.0; if (state.percentage !== 0.0) { whole = (state.amount * 100.0) / state.percentage; } return {amount: state.amount, percentage: state.percentage, part: part, whole: whole}; }

dealUiSource:
import * as app from "./app.deal";
import * as ui from "./platform-ui.dealui-pack";

// @ui-root
export view App(state: app.AppState): View {
  ui.Root() {
    ui.Column() {
      ui.NumberField(label: "Значение", onChange: action app.ChangeAmount {value: payload}, value: state.amount)
      ui.NumberField(label: "Процент", onChange: action app.ChangePercentage {value: payload}, value: state.percentage)
      ui.NumberStat(label: "Процент от значения", value: state.part)
      ui.NumberStat(label: "Целое, если значение — этот процент", value: state.whole)
      ui.Button(onClick: action app.Calculate {}, text: "Рассчитать")
      ui.Text(value: "Процент — это доля из 100. Чтобы найти P% от значения, умножьте значение на P и разделите на 100. Чтобы найти целое, если значение составляет P%, умножьте значение на 100 и разделите на P. При P = 0 обратный расчёт недоступен.")
    }
  }
}
